/**
 * An enumeration of container database types.
 *
 * An app container has a public database with data that’s accessible to all users and a private database with data that’s accessible only to the current user. A shared database allows a user to optionally grant access to a portion of their private database to another user. A database takes requests for data and applies them to the appropriate part of the container.
 *
 * API schema: CKDatabaseType
 * API version: 1.3.2
 */
export declare enum CKDatabaseType {
    "PRIVATE" = "PRIVATE",
    "PUBLIC" = "PUBLIC",
    "SHARED" = "SHARED"
}
